import{_ as a,o as n,a as p,b as l}from"./app.BAU4IqPF.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据结构(TensorAPI，试验特性)","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/data_structure_TensorAPI"},{"text":"Tensor数据结构","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/tensor_structure"},{"text":"MakeTensor","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeTensor"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeTensor.md","filePath":"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeTensor.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1785845486000}'),t={name:"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeTensor.md"};function c(e,s,r,o,i,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>MakeTensor</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本接口为试验接口，在后续版本中可能会调整或改进，不保证后续兼容性。请开发者在使用过程中关注后续版本更新。</p></div><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>需要包含的头文件为：#include &quot;tensor_api/tensor.h&quot;。</p><p>MakeTensor负责将内存指针（由<a href="MakeMemPtr.html">MakeMemPtr</a>生成）与布局对象（由<a href="../layout_structure/MakeFrameLayout.html">MakeFrameLayout</a>/<a href="../layout_structure/MakeLayout.html">MakeLayout</a>生成）绑定，生成带有完整类型信息的Tensor对象。</p><p>MakeTensor会根据内存指针的物理位置标记，自动推导返回GlobalTensor或LocalTensor，当指针物理位置位于Global Memory（外部存储）时，返回GlobalTensor；当指针位置位于AI Core上的Local Memory（内部存储）时，返回LocalTensor。</p><p>生成的Tensor对象可直接传入Copy（数据搬运）和Mmad（矩阵计算）等接口，编译器会根据其Engine中的物理位置标记和Layout中的布局模式，自动选择底层硬件指令。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Iterator</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="p">...</span><span class="w"> </span><span class="n">Args</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">Iterator</span><span class="o">&amp;</span><span class="w"> </span><span class="n">iter</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Args</span><span class="o">&amp;</span><span class="p">...</span><span class="w"> </span><span class="n">args</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">iter</td><td align="left">输入</td><td align="left">迭代器，要求传入ViewEngine对象，用于创建Tensor。返回类型由该迭代器绑定的内存位置决定。</td></tr><tr><td align="left">args</td><td align="left">输入</td><td align="left">可变参数，当前支持传入一个或两个参数。<br>•当传入一个入参时：根据传入的Layout对象创建Tensor。<br>•当传入两个入参时：根据传入的参数构建Layout对象，并基于该Layout创建Tensor。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><ul><li>返回GlobalTensor&lt;TensorAttribute&lt;Engine, Layout&gt;&gt;或LocalTensor&lt;TensorAttribute&lt;Engine, Layout&gt;&gt;类型的张量对象，具体由Engine绑定的内存位置决定。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 示例1：使用GM指针和Layout创建GlobalTensor</span>
<span class="k">auto</span><span class="w"> </span><span class="n">gmPtr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="n">gmAddr</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">gmLayout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeLayout</span><span class="p">(</span><span class="n">MakeShape</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">),</span><span class="w"> </span><span class="n">MakeStride</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">gmTensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">gmPtr</span><span class="p">,</span><span class="w"> </span><span class="n">gmLayout</span><span class="p">);</span>

<span class="c1">// 示例2：使用Local Memory指针和Layout创建LocalTensor</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">tileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">;</span>
<span class="n">__cbuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">dataPtr</span><span class="p">[</span><span class="n">tileNum</span><span class="p">];</span><span class="w"> </span><span class="c1">// 初始化</span>
<span class="k">auto</span><span class="w"> </span><span class="n">ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">dataPtr</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeFrameLayout</span><span class="o">&lt;</span><span class="n">NZLayoutPtn</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">ptr</span><span class="p">,</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>

<span class="c1">// 示例3：使用指针和布局形状创建张量</span>
<span class="k">auto</span><span class="w"> </span><span class="n">tensor2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">ptr</span><span class="p">,</span><span class="w"> </span><span class="n">MakeShape</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">),</span><span class="w"> </span><span class="n">MakeStride</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">));</span>
</code></pre></div></article></div>`,1)])])}const k=a(t,[["render",c]]);export{h as __pageData,k as default};
